206: impl ResponsesWebsocketConnection {
207:     fn new(
208:         stream: WsStream,
209:         idle_timeout: Duration,
210:         server_reasoning_included: bool,
211:         server_model: Option<String>,
212:         telemetry: Option<Arc<dyn WebsocketTelemetry>>,
213:         endpoint: ResponsesEndpoint,
214:     ) -> Self {
215:         Self {
216:             stream: Arc::new(Mutex::new(Some(stream))),
217:             endpoint,
218:             idle_timeout,
219:             server_reasoning_included,
220:             server_model,
221:             telemetry,
222:         }
223:     }
224: 
225:     pub async fn is_closed(&self) -> bool {
226:         self.stream.lock().await.is_none()
227:     }
228: 
229:     #[instrument(
230:         name = "responses_websocket.stream_request",
231:         level = "info",
232:         skip_all,
233:         fields(transport = "responses_websocket", api.path = self.endpoint.path())
234:     )]
235:     pub async fn stream_request(
236:         &self,
237:         request: ResponsesWsRequest<'_>,
238:         connection_reused: bool,
239:         turn_state: Option<Arc<OnceLock<String>>>,
240:     ) -> Result<ResponseStream, ApiError> {
241:         let (tx_event, rx_event) =
242:             mpsc::channel::<std::result::Result<ResponseEvent, ApiError>>(1600);
243:         let stream = Arc::clone(&self.stream);
244:         let idle_timeout = self.idle_timeout;
245:         let server_reasoning_included = self.server_reasoning_included;
246:         let server_model = self.server_model.clone();
247:         let telemetry = self.telemetry.clone();
248:         let ResponsesWsRequest::ResponseCreate(ws_request) = &request;
249:         let client_metadata = ws_request.client_metadata.as_ref();
250:         let timing_log_context = ResponsesWebsocketTimingLogContext {
251:             model: ws_request.model.to_string(),
252:             session_id: client_metadata
253:                 .and_then(|metadata| metadata.get(SESSION_ID_CLIENT_METADATA_KEY))
254:                 .cloned(),
255:             thread_id: client_metadata
256:                 .and_then(|metadata| metadata.get(THREAD_ID_CLIENT_METADATA_KEY))
257:                 .cloned(),
258:             turn_id: client_metadata
259:                 .and_then(|metadata| metadata.get(TURN_ID_CLIENT_METADATA_KEY))
260:                 .cloned(),
261:             traceparent: client_metadata
262:                 .and_then(|metadata| {
263:                     metadata.get(WS_REQUEST_HEADER_TRACEPARENT_CLIENT_METADATA_KEY)
264:                 })
265:                 .cloned(),
266:             previous_response_id: ws_request.previous_response_id.clone(),
267:             request_start_ms: client_metadata
268:                 .and_then(|metadata| metadata.get(WS_STREAM_REQUEST_START_MS_CLIENT_METADATA_KEY))
269:                 .cloned(),
270:             warmup: ws_request.generate == Some(false),
271:             connection_reused,
272:         };
273:         let request_text = serialize_websocket_request(&request)?;
274: 
275:         let current_span = Span::current();
276:         tokio::spawn(
277:             #[expect(
278:                 clippy::await_holding_invalid_type,
279:                 reason = "the guard serializes exclusive use of the websocket stream for the lifetime of the response stream"
280:             )]
281:             async move {
282:                 if let Some(model) = server_model {
283:                     let _ = tx_event.send(Ok(ResponseEvent::ServerModel(model))).await;
284:                 }
285:                 if server_reasoning_included {
286:                     let _ = tx_event
287:                         .send(Ok(ResponseEvent::ServerReasoningIncluded(true)))
288:                         .await;
289:                 }
290:                 let mut guard = tokio::select! {
291:                     biased;
292:                     _ = tx_event.closed() => return,
293:                     guard = stream.lock() => guard,
294:                 };
295:                 if tx_event.is_closed() {
296:                     return;
297:                 }
298:                 let result = {
299:                     let Some(ws_stream) = guard.as_mut() else {
300:                         let _ = tx_event
301:                             .send(Err(ApiError::Stream(
302:                                 "websocket connection is closed".to_string(),
303:                             )))
304:                             .await;
305:                         return;
306:                     };
307: 
308:                     tokio::select! {
309:                         biased;
310:                         result = run_websocket_response_stream(
311:                             ws_stream,
312:                             tx_event.clone(),
313:                             request_text,
314:                             idle_timeout,
315:                             telemetry,
316:                             turn_state.as_deref(),
317:                             &timing_log_context,
318:                         ) => result,
319:                         _ = tx_event.closed() => Err(ApiError::Stream(
320:                             "response event consumer dropped".to_string(),
321:                         )),
322:                     }
323:                 };
324: 
325:                 if let Err(err) = result {
326:                     // A terminal stream error should reach the caller immediately. Waiting for a
327:                     // graceful close handshake here can stall indefinitely and mask the error.
328:                     let failed_stream = guard.take();
329:                     drop(guard);
330:                     drop(failed_stream);
331:                     let _ = tx_event.send(Err(err)).await;
332:                 }
333:             }
334:             .instrument(current_span),
335:         );
336: 
337:         Ok(ResponseStream {
338:             rx_event,
339:             upstream_request_id: None,
340:         })
341:     }
342: }
