351: /// Close frame information captured by a handshake probe.
352: #[derive(Debug, Clone, PartialEq, Eq)]
353: pub struct ResponsesWebsocketClose {
354:     /// WebSocket close code returned by the server.
355:     pub code: String,
356:     /// Human-readable close reason returned by the server.
357:     pub reason: String,
