360: /// Result of a handshake-only Responses WebSocket probe.
361: #[derive(Debug, Clone, PartialEq, Eq)]
362: pub struct ResponsesWebsocketProbe {
363:     /// Redacted by callers before displaying or serializing support reports.
364:     pub url: String,
365:     /// HTTP status returned by the successful WebSocket upgrade.
366:     pub status: StatusCode,
367:     /// Whether the server reported reasoning support in the upgrade response.
368:     pub reasoning_included: bool,
369:     /// Whether the server returned a server-selected model in the upgrade response.
370:     pub server_model_present: bool,
371:     /// Close frame received immediately after upgrade, when one arrives quickly.
372:     pub immediate_close: Option<ResponsesWebsocketClose>,
373: }
