58: fn parse_turn_done(parsed: &Value) -> Option<RealtimeEvent> {
59:     let turn = parsed.get("turn")?.as_object()?;
60:     let role = turn.get("role").and_then(Value::as_str)?;
61:     let text = turn
62:         .get("transcript")
63:         .and_then(Value::as_str)
64:         .map(str::to_string)?;
65:     let done = RealtimeTranscriptDone { text };
66:     match role {
67:         "user" => Some(RealtimeEvent::InputTranscriptDone(done)),
68:         "assistant" => Some(RealtimeEvent::OutputTranscriptDone(done)),
69:         _ => None,
