506:     pub async fn next_event(&self) -> Result<Option<RealtimeEvent>, ApiError> {
507:         if self.is_closed.load(Ordering::SeqCst) {
508:             return Ok(None);
509:         }
510: 
511:         if let Some(event) = self.pending_events.lock().await.pop_front() {
512:             return Ok(Some(event));
513:         }
514: 
515:         loop {
516:             let msg = match self.rx_message.recv().await {
517:                 Ok(Ok(msg)) => msg,
518:                 Ok(Err(err)) => {
519:                     self.is_closed.store(true, Ordering::SeqCst);
520:                     error!("realtime websocket read failed: {err}");
521:                     return Err(ApiError::Stream(format!(
522:                         "failed to read websocket message: {err}"
523:                     )));
524:                 }
525:                 Err(_) => {
526:                     self.is_closed.store(true, Ordering::SeqCst);
527:                     if self.event_parser == RealtimeEventParser::FramelessBidi {
528:                         error!("realtime websocket event stream ended unexpectedly");
529:                         return Err(ApiError::Stream(
530:                             "realtime websocket event stream ended unexpectedly".to_string(),
531:                         ));
532:                     }
533:                     info!("realtime websocket event stream ended");
534:                     return Ok(None);
535:                 }
536:             };
537: 
538:             match msg {
539:                 Message::Text(text) => {
540:                     trace!(target: REALTIME_WIRE_LOG_TARGET, "realtime websocket event: {text}");
541:                     if let Some(mut event) = parse_realtime_event(&text, self.event_parser) {
542:                         self.update_active_transcript(&mut event).await;
543:                         debug!(?event, "realtime websocket parsed event");
544:                         return Ok(Some(event));
545:                     }
546:                     debug!("realtime websocket ignored unsupported text frame");
547:                 }
548:                 Message::Close(frame) => {
549:                     self.is_closed.store(true, Ordering::SeqCst);
550:                     info!(
551:                         "realtime websocket closed: code={:?} reason={:?}",
552:                         frame.as_ref().map(|frame| frame.code),
553:                         frame.as_ref().map(|frame| frame.reason.as_str())
554:                     );
555:                     if self.event_parser != RealtimeEventParser::FramelessBidi {
556:                         return Ok(None);
557:                     }
558:                     return match frame {
559:                         Some(frame) if frame.code == CloseCode::Normal => Ok(None),
560:                         Some(frame) => Err(ApiError::Stream(format!(
561:                             "realtime websocket closed unexpectedly: code={:?} reason={:?}",
562:                             frame.code, frame.reason
563:                         ))),
564:                         None => Err(ApiError::Stream(
565:                             "realtime websocket closed unexpectedly without a status code"
566:                                 .to_string(),
567:                         )),
568:                     };
569:                 }
570:                 Message::Binary(_) => {
571:                     return Ok(Some(RealtimeEvent::Error(
572:                         "unexpected binary realtime websocket event".to_string(),
573:                     )));
574:                 }
575:                 Message::Frame(_) | Message::Ping(_) | Message::Pong(_) => {}
576:             }
577:         }
578:     }
