1021: fn webrtc_sideband_session_ended(err: &ApiError) -> bool {
1022:     matches!(
1023:         err,
1024:         ApiError::Api { status, .. }
1025:             if matches!(*status, StatusCode::NOT_FOUND | StatusCode::GONE)
1026:     )
1027: }
