1029: fn map_realtime_websocket_connect_error(err: WsError) -> ApiError {
1030:     match err {
1031:         WsError::Http(response) => ApiError::Api {
1032:             status: response.status(),
1033:             message: "realtime websocket handshake failed".to_string(),
1034:         },
1035:         err => ApiError::Stream(format!("failed to connect realtime websocket: {err}")),
1036:     }
1037: }
