1039: fn merge_request_headers(
1040:     provider_headers: &HeaderMap,
1041:     extra_headers: HeaderMap,
1042:     default_headers: HeaderMap,
1043: ) -> HeaderMap {
1044:     let mut headers = provider_headers.clone();
1045:     headers.extend(extra_headers);
1046:     for (name, value) in &default_headers {
1047:         if let http::header::Entry::Vacant(entry) = headers.entry(name) {
1048:             entry.insert(value.clone());
1049:         }
1050:     }
1051:     headers
1052: }
