1054: fn with_session_id_header(
1055:     mut headers: HeaderMap,
1056:     session_id: Option<&str>,
1057: ) -> Result<HeaderMap, ApiError> {
1058:     let Some(session_id) = session_id else {
1059:         return Ok(headers);
1060:     };
1061:     headers.insert(
1062:         "x-session-id",
1063:         HeaderValue::from_str(session_id).map_err(|err| {
1064:             ApiError::Stream(format!("invalid realtime session id header: {err}"))
1065:         })?,
1066:     );
1067:     Ok(headers)
1068: }
