1163: fn normalize_realtime_path(url: &mut Url, event_parser: RealtimeEventParser) {
1164:     if event_parser == RealtimeEventParser::FramelessBidi {
1165:         let path = url.path().to_string();
1166:         if path.is_empty() || path == "/" || path == "/v1" || path == "/v1/" {
1167:             url.set_path("/v1/live");
1168:         } else if let Some(prefix) = path.trim_end_matches('/').strip_suffix("/realtime") {
1169:             url.set_path(&format!("{prefix}/live"));
1170:         } else if path.ends_with("/live/") {
1171:             url.set_path(path.trim_end_matches('/'));
1172:         }
1173:         return;
1174:     }
1175: 
1176:     let path = url.path().to_string();
1177:     if path.is_empty() || path == "/" {
1178:         url.set_path("/v1/realtime");
1179:         return;
1180:     }
1181: 
1182:     if path.ends_with("/realtime") {
1183:         return;
1184:     }
1185: 
1186:     if path.ends_with("/realtime/") {
1187:         url.set_path(path.trim_end_matches('/'));
1188:         return;
1189:     }
1190: 
1191:     if path.ends_with("/v1") {
1192:         url.set_path(&format!("{path}/realtime"));
1193:         return;
1194:     }
1195: 
1196:     if path.ends_with("/v1/") {
1197:         url.set_path(&format!("{path}realtime"));
1198:     }
1199: }
